// Pick n items from a pool, always keeping the first `keep` (the essentials), in pool order.
function v3PickSome(pool, n, keep) {
  if (!Array.isArray(pool)) return [];
  if (pool.length <= n) return pool.slice();
  keep = Math.min(keep || 0, n);
  const head = pool.slice(0, keep), rest = pool.slice(keep), chosen = [];
  while (chosen.length < n - keep && rest.length) chosen.push(rest.splice(Math.floor((typeof v3Rand === 'function' ? v3Rand() : Math.random()) * rest.length), 1)[0]);
  return head.concat(pool.filter(function (x) { return chosen.indexOf(x) > -1; }));
}
// The copy for a business: its category's pools, refined by the first matching sub-type.
function v3CopyFor(type, cat) {
  const base = V3_COPYBOOK[cat] || V3_COPYBOOK.generic;
  const t = String(type || '').toLowerCase();
  const sub = V3_SUBTYPES.find(function (s) { return s.cat === cat && s.re.test(t); });
  return sub ? Object.assign({}, base, sub) : base;
}

